insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('disena-un-plan-de-mejora-para-un-espacio-de-uso-comun','ciudades',array['sociedad','educacion']::text[],'Diseña un plan de mejora para un espacio de uso común','Elige un espacio de uso común, como el patio de un colegio, una escalera de un edificio o un parque, y elabora un plan de mejora completo con diagnóstico, propuestas, costos, etapas y responsables.','Plan','4 a 6 semanas',30,array['Plan de mejora','Espacios comunes']::text[],array['crear','resolver']::text[],'propios',NULL,'arquitectura ingenieria civil administracion trabajo social diseno sociologia ingenieria industrial economia gestion de proyectos. diagnostico participativo. presupuesto basico. redaccion de planes. hoja de calculo. un editor de documentos o presentaciones. un cronograma.',$a53sld${"id": "disena-un-plan-de-mejora-para-un-espacio-de-uso-comun", "area": "ciudades", "areas2": ["sociedad", "educacion"], "titulo": "Diseña un plan de mejora para un espacio de uso común", "resumen": "Elige un espacio de uso común, como el patio de un colegio, una escalera de un edificio o un parque, y elabora un plan de mejora completo con diagnóstico, propuestas, costos, etapas y responsables.", "tipo": "Plan", "tiempo": "4 a 6 semanas", "horas": 30, "etiquetas": ["Plan de mejora", "Espacios comunes"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Administración", "Trabajo Social", "Diseño", "Sociología", "Ingeniería Industrial", "Economía"], "problema": ["Los espacios comunes son de todos y por eso, muchas veces, de nadie: nadie los mantiene ni decide cómo mejorarlos. Un plan claro ayuda a convertir buenas ideas en acciones posibles.", "Redactar un plan es una habilidad muy útil, porque obliga a pensar en quién hace qué, con qué recursos y en qué orden."], "desarrollar": ["Elige un espacio, haz un diagnóstico con observación y conversaciones con usuarios, define los problemas principales y los objetivos de la mejora.", "Diseña cinco acciones concretas con costo, responsable y plazo, ordénalas por etapas, define cómo se mediría el éxito y preséntalo en un documento o presentación de cinco páginas."], "ampliaciones": [{"titulo": "Fuentes de recursos", "aporta": "investiga cómo se podría financiar la mejora."}, {"titulo": "Plan de mantenimiento", "aporta": "agrega cómo se cuidaría el espacio después de la mejora."}, {"titulo": "Presentación a la autoridad", "aporta": "prepara una versión corta para presentarla a quien decide."}], "objetivos": ["Hacer un diagnóstico participativo.", "Definir objetivos y acciones.", "Planificar costos, plazos y responsables.", "Definir cómo medir el éxito."], "habilidades": ["Gestión de proyectos.", "Diagnóstico participativo.", "Presupuesto básico.", "Redacción de planes."], "herramientas": ["Hoja de cálculo.", "Un editor de documentos o presentaciones.", "Un cronograma."], "lineamientos": ["Presenta el plan como una propuesta y no como una decisión; no realices cambios sin autorización.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo formato sirve para planes de mejora de un colegio, una empresa o una organización estudiantil."}$a53sld$::jsonb,69),
('se-usan-los-puentes-peatonales-por-que-la-gente-cruza-por-abajo','ciudades',array['sociedad','salud']::text[],'¿Se usan los puentes peatonales? Por qué la gente cruza por abajo','Observa cuántas personas usan un puente peatonal y cuántas cruzan por la pista, y descubre qué hace que un puente se use o se ignore.','Investigación','~20 h',20,array['Puentes peatonales','Comportamiento']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria civil psicologia sociologia arquitectura ingenieria industrial estadistica trabajo social diseno observacion de campo. entrevistas breves. analisis de comportamiento. propuestas de diseno. contadores manuales. una guia de preguntas breves. hoja de calculo.',$a54sld${"id": "se-usan-los-puentes-peatonales-por-que-la-gente-cruza-por-abajo", "area": "ciudades", "areas2": ["sociedad", "salud"], "titulo": "¿Se usan los puentes peatonales? Por qué la gente cruza por abajo", "resumen": "Observa cuántas personas usan un puente peatonal y cuántas cruzan por la pista, y descubre qué hace que un puente se use o se ignore.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Puentes peatonales", "Comportamiento"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Psicología", "Sociología", "Arquitectura", "Ingeniería Industrial", "Estadística", "Trabajo Social", "Diseño"], "problema": ["En muchas ciudades hay puentes peatonales que casi nadie usa, mientras las personas cruzan por debajo entre los autos. Esto suele explicarse como falta de educación, pero muchas veces el problema es el diseño: es largo, empinado, oscuro, inseguro o desvía demasiado.", "Entender las razones permite diseñar cruces que la gente sí use, y no solo culpar a quienes cruzan."], "desarrollar": ["Elige un puente peatonal y cuenta durante varios periodos cuántas personas lo usan y cuántas cruzan por la pista cerca de él, y mide el desvío extra que implica usar el puente y el esfuerzo de subir y bajar.", "Conversa con quince cruzantes sobre por qué eligen una u otra opción, clasifica sus respuestas y propón mejoras de diseño o de ubicación, o alternativas a nivel."], "ampliaciones": [{"titulo": "Distintos puentes", "aporta": "compara varios puentes y qué características tienen los más usados."}, {"titulo": "Tiempo extra", "aporta": "calcula cuánto tarda cruzar por el puente frente a cruzar por la pista."}, {"titulo": "Alternativas", "aporta": "evalúa un cruce a nivel con semáforo como opción."}], "objetivos": ["Contar usos con método.", "Medir esfuerzo y desvío.", "Entender razones de comportamiento.", "Proponer mejoras de diseño."], "habilidades": ["Observación de campo.", "Entrevistas breves.", "Análisis de comportamiento.", "Propuestas de diseño."], "herramientas": ["Contadores manuales.", "Una guía de preguntas breves.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No cruces por la pista para observar ni insistas a las personas que respondan, y evita juzgarlas.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo enfoque sirve para entender por qué no se usan escaleras, rampas o pasos peatonales en otros lugares."}$a54sld$::jsonb,70),
('mototaxis-combis-y-colectivos-el-transporte-que-no-sale-en-los-m','ciudades',array['negocios','sociedad']::text[],'Mototaxis, combis y colectivos: el transporte que no sale en los mapas oficiales','Estudia cómo funcionan los medios de transporte informales o no regulados de tu zona, quiénes los usan, cuánto cuestan y qué necesidades cubren que el transporte oficial no atiende.','Investigación','~24 h',24,array['Transporte informal','Movilidad']::text[],array['investigar']::text[],'propios',NULL,'economia sociologia ingenieria civil geografia administracion derecho trabajo social antropologia investigacion de campo. entrevistas. analisis comparativo. analisis critico. una guia de entrevista. un mapa en linea. hoja de calculo.',$a55sld${"id": "mototaxis-combis-y-colectivos-el-transporte-que-no-sale-en-los-m", "area": "ciudades", "areas2": ["negocios", "sociedad"], "titulo": "Mototaxis, combis y colectivos: el transporte que no sale en los mapas oficiales", "resumen": "Estudia cómo funcionan los medios de transporte informales o no regulados de tu zona, quiénes los usan, cuánto cuestan y qué necesidades cubren que el transporte oficial no atiende.", "tipo": "Investigación", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Transporte informal", "Movilidad"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Sociología", "Ingeniería Civil", "Geografía", "Administración", "Derecho", "Trabajo Social", "Antropología"], "problema": ["En muchas zonas, el transporte que más se usa no está en los mapas oficiales: mototaxis, combis, colectivos o triciclos. Cubren trayectos que el sistema formal no alcanza, pero también tienen problemas de seguridad, de regulación y de comodidad.", "Entenderlos sin prejuicios permite ver qué hace falta para integrar o mejorar el servicio."], "desarrollar": ["Elige una zona donde existan estos servicios y registra con observación sus rutas aproximadas, sus tarifas, sus horarios y sus puntos de espera, y conversa con usuarios y conductores que acepten.", "Mapea el servicio, compara tarifas y tiempos con el transporte formal para los mismos trayectos y concluye qué necesidades cubre, qué riesgos tiene y qué mejoras se podrían proponer."], "ampliaciones": [{"titulo": "Economía de un conductor", "aporta": "estima cuánto gana y cuánto gasta un conductor al día, con su permiso."}, {"titulo": "Seguridad", "aporta": "revisa las condiciones de seguridad para pasajeros."}, {"titulo": "Integración", "aporta": "propón cómo podrían integrarse con el sistema formal."}], "objetivos": ["Registrar un servicio informal con método.", "Comparar con el transporte formal.", "Entender necesidades cubiertas.", "Proponer mejoras."], "habilidades": ["Investigación de campo.", "Entrevistas.", "Análisis comparativo.", "Análisis crítico."], "herramientas": ["Una guía de entrevista.", "Un mapa en línea.", "Hoja de cálculo."], "lineamientos": ["Pide consentimiento a quienes entrevistes y no tomes datos de placas, nombres ni números de licencia.", "Evita juzgar a quienes trabajan o usan estos servicios, y no recomiendes usar vehículos que no cumplan normas de seguridad.", "Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro."], "otroSector": "El mismo estudio sirve para entender otras economías informales, como el comercio ambulante o el reciclaje."}$a55sld$::jsonb,71),
('cuanto-espacio-de-la-calle-es-para-autos-y-cuanto-para-personas','ciudades',array['ambiente','sociedad']::text[],'¿Cuánto espacio de la calle es para autos y cuánto para personas?','Mide cuánto espacio ocupa cada tipo de uso en una calle, como autos en movimiento, autos estacionados, veredas y ciclovías, y compáralo con cuántas personas se mueven en cada modo.','Análisis','~20 h',20,array['Espacio vial','Equidad']::text[],array['investigar']::text[],'propios',NULL,'arquitectura ingenieria civil geografia ingenieria ambiental sociologia ingenieria industrial economia diseno medicion en campo. conteo. calculo y graficos. pensamiento critico. cinta metrica. contadores manuales. hoja de calculo.',$a56sld${"id": "cuanto-espacio-de-la-calle-es-para-autos-y-cuanto-para-personas", "area": "ciudades", "areas2": ["ambiente", "sociedad"], "titulo": "¿Cuánto espacio de la calle es para autos y cuánto para personas?", "resumen": "Mide cuánto espacio ocupa cada tipo de uso en una calle, como autos en movimiento, autos estacionados, veredas y ciclovías, y compáralo con cuántas personas se mueven en cada modo.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Espacio vial", "Equidad"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Ingeniería Civil", "Geografía", "Ingeniería Ambiental", "Sociología", "Ingeniería Industrial", "Economía", "Diseño"], "problema": ["En muchas calles la mayor parte del espacio es para autos, aunque la mayoría de las personas camina o va en bus. Esa distribución rara vez se mide, y por eso parece natural.", "Compararla con quiénes realmente usan la calle permite discutir si el reparto es equitativo."], "desarrollar": ["Elige una calle y mide cuántos metros de ancho se dedican a veredas, carriles, ciclovía y estacionamiento, y cuenta durante un tiempo cuántas personas pasan caminando, en bus, en bici y en auto.", "Calcula el espacio por persona en cada modo de transporte, grafica la comparación y discute qué cambios podrían equilibrarlo."], "ampliaciones": [{"titulo": "Varias calles", "aporta": "compara calles céntricas y de barrio."}, {"titulo": "Costo del espacio", "aporta": "estima cuánto vale el espacio ocupado por estacionamientos."}, {"titulo": "Propuesta de reparto", "aporta": "dibuja una alternativa con otro reparto del espacio."}], "objetivos": ["Medir anchos de usos de la calle.", "Contar personas por modo.", "Calcular espacio por persona.", "Discutir la equidad del reparto."], "habilidades": ["Medición en campo.", "Conteo.", "Cálculo y gráficos.", "Pensamiento crítico."], "herramientas": ["Cinta métrica.", "Contadores manuales.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen.", "Presenta tus datos de forma neutral y evita descalificar a quienes usan auto."], "otroSector": "El mismo análisis sirve para el reparto de espacio en un campus, un aeropuerto o una plaza."}$a56sld$::jsonb,72),
('rutas-de-evacuacion-y-zonas-seguras-sabe-tu-comunidad-adonde-ir','ciudades',array['sociedad','salud']::text[],'Rutas de evacuación y zonas seguras: ¿sabe tu comunidad adónde ir?','Revisa si las rutas y puntos de reunión de emergencia de tu entorno están claros, señalizados y son conocidos por la gente, y diseña una mejora en información y señalización.','Plan','~22 h',22,array['Evacuación','Sismos']::text[],array['resolver','crear']::text[],'propios',NULL,'ingenieria civil arquitectura geografia ingenieria ambiental trabajo social educacion sociologia ingenieria de sistemas evaluacion de riesgos. observacion de campo. encuestas breves. comunicacion de riesgos. un plano en linea. una guia de verificacion. un formulario anonimo.',$a57sld${"id": "rutas-de-evacuacion-y-zonas-seguras-sabe-tu-comunidad-adonde-ir", "area": "ciudades", "areas2": ["sociedad", "salud"], "titulo": "Rutas de evacuación y zonas seguras: ¿sabe tu comunidad adónde ir?", "resumen": "Revisa si las rutas y puntos de reunión de emergencia de tu entorno están claros, señalizados y son conocidos por la gente, y diseña una mejora en información y señalización.", "tipo": "Plan", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Evacuación", "Sismos"], "intencion": ["resolver", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Civil", "Arquitectura", "Geografía", "Ingeniería Ambiental", "Trabajo Social", "Educación", "Sociología", "Ingeniería de Sistemas"], "problema": ["Lima y otras ciudades del Perú están expuestas a sismos y, en la costa, a tsunamis. En una emergencia, saber adónde ir y por dónde cambia mucho el resultado.", "Pero muchas veces las rutas no están señalizadas, están bloqueadas o simplemente nadie las conoce."], "desarrollar": ["Elige un colegio, edificio o barrio, y verifica si existen rutas y zonas seguras señalizadas, si están despejadas y si las personas saben dónde están, con una encuesta breve y anónima.", "Dibuja un plano con las rutas, mide la distancia y el tiempo a pie hasta el punto seguro, identifica obstáculos y propón mejoras de señalización y de comunicación."], "ampliaciones": [{"titulo": "Simulacro observado", "aporta": "observa un simulacro y mide cuánto tarda la evacuación."}, {"titulo": "Personas con movilidad reducida", "aporta": "analiza cómo evacuarían quienes no pueden usar escaleras."}, {"titulo": "Plan familiar", "aporta": "diseña un plan familiar de emergencia fácil de recordar."}], "objetivos": ["Verificar rutas y señalización.", "Medir distancias y tiempos.", "Conocer el nivel de información.", "Proponer mejoras."], "habilidades": ["Evaluación de riesgos.", "Observación de campo.", "Encuestas breves.", "Comunicación de riesgos."], "herramientas": ["Un plano en línea.", "Una guía de verificación.", "Un formulario anónimo."], "lineamientos": ["Usa fuentes oficiales, como las de Defensa Civil, para definir zonas seguras; tu trabajo es un diagnóstico y no reemplaza un plan oficial.", "Evita generar alarma y no propongas ninguna medida que contradiga las indicaciones oficiales."], "otroSector": "El mismo método sirve para evacuación de incendios, de eventos masivos o de un edificio de oficinas."}$a57sld$::jsonb,73),
('un-mercado-de-abastos-como-infraestructura-del-barrio','ciudades',array['negocios','agricultura']::text[],'Un mercado de abastos como infraestructura del barrio','Estudia un mercado de abastos de tu zona como una pieza de infraestructura: cómo funciona, qué aporta al barrio, qué condiciones tiene y qué mejoras necesita.','Análisis','~24 h',24,array['Mercados','Alimentos']::text[],array['investigar']::text[],'propios',NULL,'economia arquitectura sociologia administracion ingenieria agroindustrial geografia salud publica trabajo social observacion de campo. entrevistas. analisis de espacios. propuestas de mejora. una ficha de evaluacion. un plano a mano. hoja de calculo.',$a58sld${"id": "un-mercado-de-abastos-como-infraestructura-del-barrio", "area": "ciudades", "areas2": ["negocios", "agricultura"], "titulo": "Un mercado de abastos como infraestructura del barrio", "resumen": "Estudia un mercado de abastos de tu zona como una pieza de infraestructura: cómo funciona, qué aporta al barrio, qué condiciones tiene y qué mejoras necesita.", "tipo": "Análisis", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Mercados", "Alimentos"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Arquitectura", "Sociología", "Administración", "Ingeniería Agroindustrial", "Geografía", "Salud Pública", "Trabajo Social"], "problema": ["Un mercado de abastos no es solo un lugar de compra: concentra empleo, abastecimiento de alimentos, encuentro social y tradición. Pero muchos tienen problemas de higiene, desorden, ventilación, seguridad y circulación.", "Mirarlo como infraestructura permite pensar en su mejora sin perder lo que hace valioso al mercado."], "desarrollar": ["Con permiso de la administración, recorre un mercado y registra su distribución, sus accesos, la circulación, la ventilación, la limpieza y los servicios, y cuenta cuántos puestos hay por rubro.", "Conversa con cinco comerciantes y cinco compradores, resume las fortalezas y los problemas, y propón mejoras de bajo costo en orden, limpieza, circulación y seguridad."], "ampliaciones": [{"titulo": "Flujo de personas", "aporta": "mapea por dónde circula la gente y dónde hay aglomeraciones."}, {"titulo": "Cadena de abastecimiento", "aporta": "investiga de dónde vienen los productos y cómo llegan."}, {"titulo": "Alternativas de diseño", "aporta": "dibuja un rediseño de la distribución interna."}], "objetivos": ["Evaluar un mercado como infraestructura.", "Escuchar a los actores.", "Identificar problemas.", "Proponer mejoras viables."], "habilidades": ["Observación de campo.", "Entrevistas.", "Análisis de espacios.", "Propuestas de mejora."], "herramientas": ["Una ficha de evaluación.", "Un plano a mano.", "Hoja de cálculo."], "lineamientos": ["Pide permiso a la administración antes de recorrer y entrevistar, no fotografíes a personas ni a los productos de los puestos sin autorización.", "Presenta tus resultados con respeto hacia comerciantes y compradores."], "otroSector": "El mismo análisis sirve para un terminal, un centro de abastos, un mall o un centro comercial."}$a58sld$::jsonb,74),
('puede-un-nino-jugar-seguro-en-tu-barrio','ciudades',array['sociedad','salud']::text[],'¿Puede un niño jugar seguro en tu barrio?','Evalúa qué espacios tienen los niños de tu barrio para jugar y moverse con seguridad, cuántos hay, en qué estado están y quiénes quedan sin acceso.','Investigación','~22 h',22,array['Infancia','Juego']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura psicologia educacion sociologia trabajo social ingenieria civil salud publica diseno evaluacion de espacios. observacion. entrevistas. diseno de propuestas. una ficha de evaluacion. un mapa en linea. hoja de calculo.',$a59sld${"id": "puede-un-nino-jugar-seguro-en-tu-barrio", "area": "ciudades", "areas2": ["sociedad", "salud"], "titulo": "¿Puede un niño jugar seguro en tu barrio?", "resumen": "Evalúa qué espacios tienen los niños de tu barrio para jugar y moverse con seguridad, cuántos hay, en qué estado están y quiénes quedan sin acceso.", "tipo": "Investigación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Infancia", "Juego"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Psicología", "Educación", "Sociología", "Trabajo Social", "Ingeniería Civil", "Salud Pública", "Diseño"], "problema": ["Los niños necesitan espacios cercanos, seguros y variados para jugar. Pero en muchos barrios los parques están lejos, mal mantenidos, ocupados por autos o inseguros, y los niños juegan en la pista o se quedan en casa.", "Mapear esos espacios permite ver qué zonas dejan a los niños sin lugares para jugar."], "desarrollar": ["Recorre una zona, identifica los espacios aptos para el juego infantil, como parques, canchas o patios, y evalúa seguridad, estado de los juegos, sombra, limpieza, distancia a las viviendas y cruces que hay que atravesar.", "Elabora un mapa con el puntaje de cada lugar, pregunta a cinco padres o cuidadores qué los hace elegir un lugar o evitarlo, y propón mejoras de bajo costo."], "ampliaciones": [{"titulo": "Juego en la calle", "aporta": "analiza qué calles podrían cerrarse en ciertos horarios para el juego."}, {"titulo": "Distintas edades", "aporta": "compara las necesidades de niños pequeños, escolares y adolescentes."}, {"titulo": "Voz de los niños", "aporta": "con permiso, diseña una actividad donde los niños dibujen el lugar que les gustaría."}], "objetivos": ["Evaluar espacios de juego.", "Mapear su disponibilidad.", "Escuchar a quienes cuidan niños.", "Proponer mejoras."], "habilidades": ["Evaluación de espacios.", "Observación.", "Entrevistas.", "Diseño de propuestas."], "herramientas": ["Una ficha de evaluación.", "Un mapa en línea.", "Hoja de cálculo."], "lineamientos": ["No fotografíes ni grabes a niños, y si trabajas con menores, hazlo con autorización de sus familias y de una institución.", "Observa desde lejos y no interactúes con niños que no conoces.", "Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro."], "otroSector": "El mismo estudio sirve para espacios de juego dentro de un colegio, un hospital pediátrico o un centro comunitario."}$a59sld$::jsonb,75),
('donde-se-acumula-la-basura-en-tu-barrio-y-por-que','ciudades',array['ambiente','salud']::text[],'¿Dónde se acumula la basura en tu barrio y por qué?','Mapea los puntos donde se acumula basura en tu zona, investiga qué los provoca, como horarios de recojo o falta de tachos, y propone soluciones que la comunidad pueda aplicar.','Análisis','~20 h',20,array['Residuos','Puntos críticos']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental geografia salud publica ingenieria civil sociologia trabajo social estadistica ingenieria industrial registro de campo. mapeo. analisis de causas. diseno de soluciones. una ficha de registro. un mapa en linea. hoja de calculo.',$a60sld${"id": "donde-se-acumula-la-basura-en-tu-barrio-y-por-que", "area": "ciudades", "areas2": ["ambiente", "salud"], "titulo": "¿Dónde se acumula la basura en tu barrio y por qué?", "resumen": "Mapea los puntos donde se acumula basura en tu zona, investiga qué los provoca, como horarios de recojo o falta de tachos, y propone soluciones que la comunidad pueda aplicar.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Residuos", "Puntos críticos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Geografía", "Salud Pública", "Ingeniería Civil", "Sociología", "Trabajo Social", "Estadística", "Ingeniería Industrial"], "problema": ["Los puntos críticos de basura se repiten: esquinas, terrenos baldíos o riberas donde cada día aparecen más residuos. No siempre es falta de educación, a veces faltan tachos, horarios de recojo claros o lugares autorizados.", "Entender por qué ocurre en cada punto permite plantear soluciones adaptadas, y no solo campañas generales."], "desarrollar": ["Recorre tu zona y registra los puntos donde se acumula basura, qué tipo de residuos hay, cuánto, con qué frecuencia reaparece y qué hay cerca, como tachos, paraderos o comercios.", "Conversa con vecinos y con un trabajador del recojo, si es posible, sobre los horarios y problemas, y propón una solución distinta para cada tipo de punto, con su costo y un responsable."], "ampliaciones": [{"titulo": "Horarios del recojo", "aporta": "relaciona la acumulación con los días y horas de recojo."}, {"titulo": "Residuos reaprovechables", "aporta": "identifica cuánto de lo que se acumula podría reciclarse."}, {"titulo": "Campaña vecinal", "aporta": "diseña una campaña con mensajes basados en tus hallazgos."}], "objetivos": ["Mapear puntos críticos de residuos.", "Identificar causas.", "Escuchar a vecinos y trabajadores.", "Proponer soluciones concretas."], "habilidades": ["Registro de campo.", "Mapeo.", "Análisis de causas.", "Diseño de soluciones."], "herramientas": ["Una ficha de registro.", "Un mapa en línea.", "Hoja de cálculo."], "lineamientos": ["Haz las observaciones de día, en grupo y desde espacios públicos; no te expongas al tráfico ni a zonas donde no te sientas seguro.", "No manipules residuos ni los toques sin protección; observa y registra a distancia.", "No fotografíes ni grabes a personas identificables ni anotes datos que las identifiquen."], "otroSector": "El mismo mapa sirve para puntos de ruido, de grafitis, de cables caídos o de luminarias malogradas."}$a60sld$::jsonb,76),
('que-tan-conectado-digitalmente-esta-tu-barrio','ciudades',array['tecnologia','sociedad']::text[],'¿Qué tan conectado digitalmente está tu barrio?','Mide la cobertura móvil, la velocidad de internet y los puntos de wifi público de tu barrio, y descubre qué zonas quedan desconectadas y qué efecto tiene eso en el estudio y el trabajo.','Análisis','~22 h',22,array['Conectividad','Internet']::text[],array['investigar']::text[],'propios',NULL,'ingenieria de sistemas ingenieria electronica telecomunicaciones geografia sociologia economia estadistica educacion medicion con aplicaciones. cartografia. analisis de datos. propuestas de mejora. una aplicacion de prueba de velocidad. un mapa en linea. hoja de calculo.',$a61sld${"id": "que-tan-conectado-digitalmente-esta-tu-barrio", "area": "ciudades", "areas2": ["tecnologia", "sociedad"], "titulo": "¿Qué tan conectado digitalmente está tu barrio?", "resumen": "Mide la cobertura móvil, la velocidad de internet y los puntos de wifi público de tu barrio, y descubre qué zonas quedan desconectadas y qué efecto tiene eso en el estudio y el trabajo.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Conectividad", "Internet"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Electrónica", "Telecomunicaciones", "Geografía", "Sociología", "Economía", "Estadística", "Educación"], "problema": ["La conexión a internet se ha vuelto una infraestructura básica para estudiar, trabajar y hacer trámites. Pero no llega igual a todos los lugares: hay zonas con mala señal, internet lento o muy caro.", "Medirla permite ver la brecha digital dentro de una ciudad y no solo entre regiones."], "desarrollar": ["Elige una zona y mide, en varios puntos y horarios, la velocidad de internet móvil con una aplicación de pruebas, la intensidad de señal y la existencia de wifi público.", "Haz un mapa de calidad de conexión, compara con la cantidad de personas que dependen de internet para estudiar, y propón dónde convendría instalar puntos de acceso o mejoras."], "ampliaciones": [{"titulo": "Costo de la conexión", "aporta": "calcula cuánto paga un hogar por internet y compara zonas."}, {"titulo": "Horas pico", "aporta": "analiza cuánto baja la velocidad por la noche."}, {"titulo": "Efecto en el estudio", "aporta": "pregunta de forma anónima a estudiantes cómo les afecta la mala conexión."}], "objetivos": ["Medir conectividad con método.", "Mapear calidad de conexión.", "Relacionarla con necesidades.", "Proponer mejoras."], "habilidades": ["Medición con aplicaciones.", "Cartografía.", "Análisis de datos.", "Propuestas de mejora."], "herramientas": ["Una aplicación de prueba de velocidad.", "Un mapa en línea.", "Hoja de cálculo."], "lineamientos": ["Mide solo desde lugares públicos o propios, sin conectarte a redes privadas ni vulnerar accesos.", "No publiques claves ni datos de redes de otras personas."], "otroSector": "El mismo estudio sirve para evaluar la cobertura en un campus, un hospital rural o una zona de trabajo remoto."}$a61sld$::jsonb,77),
('que-barrios-se-calientan-mas-calor-techos-y-sombra','ciudades',array['ambiente','ciencias']::text[],'¿Qué barrios se calientan más? Calor, techos y sombra','Mide la temperatura en distintos puntos de tu zona y descubre cómo influyen la sombra, el cemento, los árboles y los techos en el calor que se siente en la calle.','Análisis','~24 h',24,array['Isla de calor','Sombra']::text[],array['investigar']::text[],'propios',NULL,'ingenieria ambiental geografia arquitectura fisica ingenieria civil ciencia de datos estadistica salud publica medicion con instrumentos. analisis estadistico basico. interpretacion de datos. propuestas de solucion. termometros o sensores. hoja de calculo. un mapa en linea.',$a62sld${"id": "que-barrios-se-calientan-mas-calor-techos-y-sombra", "area": "ciudades", "areas2": ["ambiente", "ciencias"], "titulo": "¿Qué barrios se calientan más? Calor, techos y sombra", "resumen": "Mide la temperatura en distintos puntos de tu zona y descubre cómo influyen la sombra, el cemento, los árboles y los techos en el calor que se siente en la calle.", "tipo": "Análisis", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Isla de calor", "Sombra"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Geografía", "Arquitectura", "Física", "Ingeniería Civil", "Ciencia de Datos", "Estadística", "Salud Pública"], "problema": ["En una misma ciudad, algunas calles son mucho más calurosas que otras: el cemento, el asfalto y los techos de calamina absorben calor, y los árboles dan frescor. Se le llama isla de calor urbana.", "Esto afecta la salud, el confort y el consumo de energía, y se puede medir con herramientas simples."], "desarrollar": ["Elige entre seis y diez puntos de tu zona con características distintas, como un parque, una calle sin árboles o una losa de cemento, y mide la temperatura del aire y de la superficie a la misma hora en varios días.", "Relaciona las diferencias con el tipo de superficie, la sombra y la cantidad de vegetación, grafica los resultados y propón tres intervenciones para refrescar los puntos más calientes."], "ampliaciones": [{"titulo": "Cámara térmica o imágenes satelitales", "aporta": "contrasta con mapas térmicos públicos de tu ciudad."}, {"titulo": "Efecto de un árbol", "aporta": "mide cuántos grados baja la temperatura bajo la sombra de un árbol."}, {"titulo": "Costo de refrescar", "aporta": "estima cuánto costaría sembrar árboles o pintar techos de claro."}], "objetivos": ["Medir temperaturas en distintos puntos.", "Relacionarlas con características del entorno.", "Interpretar patrones.", "Proponer intervenciones."], "habilidades": ["Medición con instrumentos.", "Análisis estadístico básico.", "Interpretación de datos.", "Propuestas de solución."], "herramientas": ["Termómetros o sensores.", "Hoja de cálculo.", "Un mapa en línea."], "lineamientos": ["Evita medir en horas de calor extremo sin protección, usa agua, sombrero y protector solar, y no subas a techos.", "Presenta tus resultados como mediciones de unos días, no como una caracterización completa."], "otroSector": "El mismo estudio sirve para comparar el calor en aulas, mercados o espacios de trabajo."}$a62sld$::jsonb,78),
('la-historia-de-tu-barrio-como-cambio-en-50-anos','ciudades',array['arte','sociedad']::text[],'La historia de tu barrio: cómo cambió en 50 años','Reconstruye cómo ha cambiado tu barrio en las últimas décadas, con fotos antiguas, mapas, relatos de vecinos y datos, y muestra qué se transformó y qué permanece.','Investigación','3 a 5 semanas',26,array['Historia urbana','Memoria']::text[],array['investigar','crear']::text[],'propios',NULL,'arquitectura historia sociologia antropologia geografia comunicaciones diseno educacion investigacion historica. entrevistas. lectura de mapas antiguos. narracion visual. archivos de fotos y mapas publicos. una grabadora, con permiso. un editor de linea de tiempo.',$a63sld${"id": "la-historia-de-tu-barrio-como-cambio-en-50-anos", "area": "ciudades", "areas2": ["arte", "sociedad"], "titulo": "La historia de tu barrio: cómo cambió en 50 años", "resumen": "Reconstruye cómo ha cambiado tu barrio en las últimas décadas, con fotos antiguas, mapas, relatos de vecinos y datos, y muestra qué se transformó y qué permanece.", "tipo": "Investigación", "tiempo": "3 a 5 semanas", "horas": 26, "etiquetas": ["Historia urbana", "Memoria"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Historia", "Sociología", "Antropología", "Geografía", "Comunicaciones", "Diseño", "Educación"], "problema": ["Un barrio cambia con el tiempo: aparecen nuevas calles, desaparecen lugares y cambian los usos. Esa memoria suele estar en las fotos familiares y en las conversaciones de los vecinos mayores.", "Reconstruirla ayuda a entender el presente del barrio y a valorar lo que se podría perder."], "desarrollar": ["Reúne imágenes antiguas, con permiso, mapas históricos, planos o fotos aéreas públicas, y conversa con tres o cuatro vecinos mayores sobre cómo era el barrio antes.", "Construye una línea de tiempo, compara el mapa de hace décadas con el de hoy, identifica los cambios más importantes y presenta el resultado como una exposición, un mapa o una pequeña web."], "ampliaciones": [{"titulo": "Lugares desaparecidos", "aporta": "mapea los lugares que ya no existen y su historia."}, {"titulo": "Fotografía de antes y después", "aporta": "toma fotos actuales desde el mismo ángulo que fotos antiguas."}, {"titulo": "Relatos", "aporta": "recopila tres historias cortas de vecinos."}], "objetivos": ["Reunir fuentes históricas.", "Entrevistar con respeto.", "Construir una línea de tiempo.", "Presentar los cambios del barrio."], "habilidades": ["Investigación histórica.", "Entrevistas.", "Lectura de mapas antiguos.", "Narración visual."], "herramientas": ["Archivos de fotos y mapas públicos.", "Una grabadora, con permiso.", "Un editor de línea de tiempo."], "lineamientos": ["Pide permiso para usar fotos y relatos, cuida la privacidad de las personas y no publiques imágenes de terceros sin autorización.", "Cita las fuentes de los mapas y archivos."], "otroSector": "El mismo método sirve para documentar la historia de un colegio, de un mercado, de una empresa o de una familia."}$a63sld$::jsonb,79),
('cuanto-cuesta-construir-y-mantener-una-vereda-un-parque-o-una-ci','ciudades',array['negocios','derecho']::text[],'¿Cuánto cuesta construir y mantener una vereda, un parque o una ciclovía?','Calcula con información pública cuánto cuesta construir y mantener obras urbanas pequeñas, y compáralas con otros gastos para entender qué tan caras o baratas son.','Análisis','~22 h',22,array['Costos','Obras públicas']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria civil economia arquitectura contabilidad administracion ciencias politicas estadistica derecho estimacion de costos. lectura de presupuestos publicos. calculo en hoja de calculo. analisis comparativo. hoja de calculo. portales de transparencia y de obras publicas. precios de referencia de materiales.',$a64sld${"id": "cuanto-cuesta-construir-y-mantener-una-vereda-un-parque-o-una-ci", "area": "ciudades", "areas2": ["negocios", "derecho"], "titulo": "¿Cuánto cuesta construir y mantener una vereda, un parque o una ciclovía?", "resumen": "Calcula con información pública cuánto cuesta construir y mantener obras urbanas pequeñas, y compáralas con otros gastos para entender qué tan caras o baratas son.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Costos", "Obras públicas"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Civil", "Economía", "Arquitectura", "Contabilidad", "Administración", "Ciencias Políticas", "Estadística", "Derecho"], "problema": ["Se habla mucho de que falta infraestructura, pero casi nunca se dice cuánto cuesta hacerla ni mantenerla. Una vereda, un parque o una ciclovía tienen costos de construcción y de mantenimiento en el tiempo.", "Conocer esos costos permite discutir con realismo qué se puede hacer, en cuánto tiempo y con qué presupuesto."], "desarrollar": ["Con información pública, como expedientes de obras, portales de transparencia y precios de materiales, estima el costo por metro de una vereda, de una ciclovía y de un parque pequeño.", "Calcula el costo de mantenimiento por año, compara con otros gastos de la municipalidad y estima cuánto costaría mejorar tres tramos de tu barrio."], "ampliaciones": [{"titulo": "Presupuesto detallado", "aporta": "arma el presupuesto de una mejora concreta con partidas."}, {"titulo": "Comparar obras", "aporta": "compara el costo por beneficiario de distintas obras."}, {"titulo": "Fuentes de financiamiento", "aporta": "investiga cómo se financian este tipo de obras."}], "objetivos": ["Buscar costos en información pública.", "Calcular costos de construcción y mantenimiento.", "Comparar obras.", "Estimar el costo de una mejora."], "habilidades": ["Estimación de costos.", "Lectura de presupuestos públicos.", "Cálculo en hoja de cálculo.", "Análisis comparativo."], "herramientas": ["Hoja de cálculo.", "Portales de transparencia y de obras públicas.", "Precios de referencia de materiales."], "lineamientos": ["Usa solo información pública y fecha los precios; aclara que son estimaciones y no un presupuesto oficial.", "No acuses a autoridades ni a empresas de sobrecostos sin pruebas."], "otroSector": "El mismo análisis sirve para estimar el costo de mantener un campus, una carretera o una red de agua."}$a64sld$::jsonb,80),
('quien-decide-como-es-tu-calle-normas-de-veredas-retiros-y-altura','ciudades',array['derecho','sociedad']::text[],'¿Quién decide cómo es tu calle? Normas de veredas, retiros y alturas','Descubre qué normas determinan cómo se construyen y usan las calles y los edificios de tu barrio, quién las aplica y cómo puede participar un vecino.','Guía','~22 h',22,array['Normativa urbana','Ciudadanía']::text[],array['investigar']::text[],'publicos',NULL,'derecho arquitectura ciencias politicas ingenieria civil geografia sociologia administracion comunicaciones busqueda de normas. lectura juridica basica. redaccion clara. pensamiento critico. portales oficiales. un editor de documentos. un editor de infografias.',$a65sld${"id": "quien-decide-como-es-tu-calle-normas-de-veredas-retiros-y-altura", "area": "ciudades", "areas2": ["derecho", "sociedad"], "titulo": "¿Quién decide cómo es tu calle? Normas de veredas, retiros y alturas", "resumen": "Descubre qué normas determinan cómo se construyen y usan las calles y los edificios de tu barrio, quién las aplica y cómo puede participar un vecino.", "tipo": "Guía", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Normativa urbana", "Ciudadanía"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Arquitectura", "Ciencias Políticas", "Ingeniería Civil", "Geografía", "Sociología", "Administración", "Comunicaciones"], "problema": ["El ancho de una vereda, la altura de un edificio o el uso de un terreno no son decisiones al azar: las regulan normas municipales y nacionales que la mayoría de las personas no conoce.", "Entender quién decide y con qué reglas permite hacer preguntas informadas y participar cuando se discuten cambios."], "desarrollar": ["Elige un tema, como veredas, retiros, alturas o uso de suelo, y busca en portales oficiales las normas que lo regulan en tu distrito, anotando qué dicen y quién las aplica.", "Escribe una guía en lenguaje sencillo que explique qué se puede y qué no se puede hacer, a quién acudir para consultas o reclamos y cómo puede participar un vecino."], "ampliaciones": [{"titulo": "Caso real", "aporta": "analiza un caso de tu barrio, como una obra, y qué normas se aplican."}, {"titulo": "Participación ciudadana", "aporta": "investiga los mecanismos de participación en decisiones urbanas."}, {"titulo": "Comparar distritos", "aporta": "compara la norma de dos distritos."}], "objetivos": ["Ubicar normas en fuentes oficiales.", "Entender quién decide.", "Explicarlo en lenguaje claro.", "Conocer mecanismos de participación."], "habilidades": ["Búsqueda de normas.", "Lectura jurídica básica.", "Redacción clara.", "Pensamiento crítico."], "herramientas": ["Portales oficiales.", "Un editor de documentos.", "Un editor de infografías."], "lineamientos": ["Usa solo fuentes oficiales y fecha tu información, porque las normas cambian con frecuencia.", "Aclara que es una guía informativa y no asesoría legal."], "otroSector": "La misma guía sirve para entender normas sobre comercio, ruido, medio ambiente o transporte."}$a65sld$::jsonb,81)
